	let start = 0;
	for (let i = 0; i <= chars.length; i++) if (i === chars.length || levels.levels[i] !== levels.levels[start]) {
		const seg = chars.slice(start, i);
		const isRtl = levels.levels[start] % 2 === 1;
		const text = isRtl ? seg.map((c) => MIRROR_PAIRS[c] ?? c).join("") : seg.join("");
		runs.push({
			text,
			level: levels.levels[start],
			isRtl
		});
		start = i;
	}
