async function loadImageForPdf(pdfDoc, url, cache) {
	if (!url) return null;
	if (cache.has(url)) return cache.get(url) ?? null;
	try {
		const res = await fetch(url);
		if (!res.ok) {
			cache.set(url, null);
			return null;
		}
		const buf = new Uint8Array(await res.arrayBuffer());
		const isPng = buf.length >= 4 && buf[0] === 137 && buf[1] === 80 && buf[2] === 78 && buf[3] === 71;
		let embedded;
		if (isPng) embedded = await pdfDoc.embedPng(buf);
		else try {
			embedded = await pdfDoc.embedJpg(buf);
		} catch {
			embedded = await pdfDoc.embedPng(buf);
		}
		cache.set(url, embedded);
		return embedded;
	} catch {
		cache.set(url, null);
		return null;
	}
}
function drawImageContain(page, img, x, y, w, h, alignBottom = false) {
	if (!img) return;
	const dims = img.scale(1);
	const scale = Math.min(w / dims.width, h / dims.height);
	const drawW = dims.width * scale;
	const drawH = dims.height * scale;
	const drawX = x + (w - drawW) / 2;
	const drawY = alignBottom ? y : y + (h - drawH) / 2;
	page.drawImage(img, {
		x: drawX,
		y: drawY,
		width: drawW,
		height: drawH
	});
}
