function toPersianDigits(num) {
	const digits = [
		"۰",
		"۱",
		"۲",
		"۳",
		"۴",
		"۵",
		"۶",
		"۷",
		"۸",
		"۹"
	];
	return String(num).replace(/\d/g, (d) => digits[Number(d)]);
}
async function fetchImageAsset(url, cache) {
	if (!url) return null;
	if (cache.has(url)) return cache.get(url) ?? null;
	try {
		if (url.startsWith("data:")) {
			const dims = await new Promise((resolve) => {
				const img = new Image();
				img.onload = () => resolve({
					w: img.naturalWidth || 100,
					h: img.naturalHeight || 100
				});
				img.onerror = () => resolve({
					w: 100,
					h: 100
				});
				img.src = url;
			});
			const asset = {
				data: url,
				width: dims.w,
				height: dims.h
			};
			cache.set(url, asset);
			return asset;
		}
		const res = await fetch(url);
		if (!res.ok) {
			cache.set(url, null);
			return null;
		}
		const blob = await res.blob();
		const dataUrl = await new Promise((resolve, reject) => {
			const reader = new FileReader();
			reader.onloadend = () => resolve(reader.result);
			reader.onerror = reject;
			reader.readAsDataURL(blob);
		});
		const dims = await new Promise((resolve) => {
			const img = new Image();
			img.onload = () => resolve({
				w: img.naturalWidth || 100,
				h: img.naturalHeight || 100
			});
			img.onerror = () => resolve({
				w: 100,
				h: 100
			});
			img.src = dataUrl;
		});
		const asset = {
			data: dataUrl,
			width: dims.w,
			height: dims.h
		};
		cache.set(url, asset);
		return asset;
	} catch {
		cache.set(url, null);
		return null;
	}
}
function addContainedImage(slide, asset, x, y, w, h) {
	if (!asset) return;
	slide.addImage({
		data: asset.data,
		x,
		y,
		w,
		h,
		sizing: {
			type: "contain",
			w,
			h
		}
	});
}
function addCoverImage(slide, asset, x, y, w, h) {
	if (!asset) return;
	slide.addImage({
		data: asset.data,
		x,
		y,
		w,
		h,
		sizing: {
			type: "cover",
			w,
			h
		}
	});
}
